const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let filter='all',query='',route={type:'home'},student={name:'',group:''};const drafts={},results={};let school={school:'MAN 4 JOMBANG',teacher:'Zainul Arifin, S.Pdi',principal:'',teacherSign:'',principalSign:'',consent:false};
let schoolLogo=document.getElementById('schoolLogoData')?.textContent.trim()||'';
function applySchoolLogo(){document.querySelectorAll('.logo,.certificate .seal').forEach(n=>{n.innerHTML=schoolLogo?'<img src="'+schoolLogo+'" alt="Logo MAN 4 JOMBANG" style="width:100%;height:100%;object-fit:contain">':'<span style="font-size:11px;line-height:1.3">MAN 4<br>JOMBANG</span>';});}
const logoObserver=new MutationObserver(()=>{document.querySelectorAll('.logo,.certificate .seal').forEach(n=>{if(n.dataset.logoApplied!==schoolLogo){n.dataset.logoApplied=schoolLogo; n.innerHTML=schoolLogo?'<img src="'+schoolLogo+'" alt="Logo MAN 4 JOMBANG" style="width:100%;height:100%;object-fit:contain">':'<span style="font-size:11px;line-height:1.3">MAN 4<br>JOMBANG</span>';}});});logoObserver.observe(document.body,{childList:true,subtree:true});
const logoButton=document.createElement('button');logoButton.dataset.runtime='true';logoButton.type='button';logoButton.className='btn secondary';logoButton.textContent='Pasang logo sekolah';document.querySelector('.tools').prepend(logoButton);const logoInput=document.createElement('input');logoInput.dataset.runtime='true';logoInput.type='file';logoInput.accept='image/jpeg,image/png';logoInput.hidden=true;document.body.appendChild(logoInput);logoButton.onclick=()=>logoInput.click();logoInput.onchange=async()=>{try{const data=await readSign(logoInput);if(data){schoolLogo=data;applySchoolLogo();logoButton.textContent='Ganti logo sekolah';}}catch(e){alert(e.message);}finally{logoInput.value='';}};

const sourceClone=document.documentElement.cloneNode(true);sourceClone.querySelectorAll('[data-runtime]').forEach(n=>n.remove());const originalHTML='<!DOCTYPE html>\n'+sourceClone.outerHTML;
function page(html){$('app').innerHTML=html;window.scrollTo({top:0,behavior:'smooth'});}
function go(type,id){route={type,id};if(type==='home')home();if(type==='lesson')lesson(id);if(type==='exam')examPage(id);if(type==='result')resultPage(id);if(type==='cert')certificate(id);}
function home(){page(`<section class="hero"><span class="eyebrow">Al-Qur’an Hadis · Fase E & F</span><h1>Ilmu yang menerangi.<br>Akhlak yang menginspirasi.</h1><p>Pelajari setiap bab, hubungkan dengan kehidupan, lalu selesaikan kuis kelasmu. Setiap usaha belajar layak diapresiasi.</p><span>✦ Kelas 10, 11, dan 12 · Sertifikat penyelesaian</span></section><div class="stats"><div class="stat"><strong>14</strong>Bab pembelajaran</div><div class="stat"><strong>75</strong>Soal dalam 3 kuis</div><div class="stat"><strong>${Object.keys(results).length} / 3</strong>Kuis diselesaikan</div></div><div class="row"><div><h2 style="margin-bottom:4px">Pilih perjalanan belajarmu</h2><span class="muted">Semua materi tersedia dalam kartu di bawah.</span></div><input id="search" class="search" type="search" placeholder="Cari materi…" aria-label="Cari materi" value="${esc(query)}"></div><div class="filters">${['all',10,11,12].map(g=>`<button class="btn secondary ${String(filter)===String(g)?'active':''}" data-filter="${g}" aria-pressed="${String(filter)===String(g)}">${g==='all'?'Semua materi':'Kelas '+g+' · Fase '+(g===10?'E':'F')}</button>`).join('')}</div><div id="cards" class="grid"></div><section class="exam-cards"><h2>✍️ Kuis akhir kelas</h2><p class="muted">Setiap kuis: 20 pilihan ganda kompleks + 5 esai. Pilihan ganda memiliki lebih dari satu jawaban benar.</p><div class="grid">${[10,11,12].map(g=>`<div class="exam-card"><h3>Kuis kelas ${g}</h3><p>${chapters.filter(c=>c.grade===g).length} bab · 25 soal · tanpa batas nilai sertifikat</p><button class="btn" data-exam="${g}">${results[g]?'Kerjakan kembali':'Mulai kuis'} →</button>${results[g]?` <button class="btn secondary" data-result="${g}">Hasil</button>`:''}</div>`).join('')}</div></section><p class="note">Materi mengikuti 14 topik yang diberikan, dengan uraian per subbab dan rujukan. Penomoran hadis dapat berbeda antar-edisi. Pengelompokan fase mengikuti brief pembelajaran ini.</p>`);cards();$('search').oninput=e=>{query=e.target.value;cards();};}
function cards(){const found=chapters.map((c,i)=>({...c,i})).filter(c=>(filter==='all'||Number(filter)===c.grade)&&(c.title+' '+c.intro).toLowerCase().includes(query.toLowerCase()));$('cards').innerHTML=found.map(c=>`<button class="card" data-lesson="${c.i}"><div class="row" style="width:100%"><span class="icon">${c.icon}</span><span class="badge">KELAS ${c.grade}</span></div><h3>${c.title}</h3><p>${c.intro}</p><div class="card-bottom"><span>${c.sections.length} subbab</span><strong>Pelajari →</strong></div></button>`).join('')||'<p class="empty">Tidak ada materi yang cocok. Coba kata kunci lain.</p>';}
function lesson(i){const c=chapters[i];page(`<button class="btn secondary" data-home>← Kembali ke dasbor</button><div class="lesson-layout"><aside class="toc"><strong>DAFTAR ISI</strong>${c.sections.map((s,j)=>`<a href="#sub${j}">${j+1}. ${s[0]}</a>`).join('')}<small>Kelas ${c.grade} · Fase ${c.grade===10?'E':'F'}</small></aside><section class="panel"><span class="badge">MATERI KELAS ${c.grade}</span><h1>${c.icon} ${c.title}</h1><p class="muted">${c.intro}</p><article class="article">${c.sections.map((s,j)=>`<section><h2 id="sub${j}">${j+1}. ${s[0]}</h2>${s.slice(1).map(p=>`<p>${p}</p>`).join('')}</section>`).join('')}<div class="source"><strong>Rujukan belajar</strong><p>${c.ref}</p><small>Uraian merupakan penjelasan pembelajaran dan parafrasa makna dalil. Untuk pendalaman, baca mushaf, tafsir, serta syarah hadis bersama guru.</small></div></article><div class="callout"><h3>Lanjutkan pemahamanmu</h3><p>Kuis kelas ${c.grade} mencakup seluruh bab di kelas ini dan terbuka pada halaman tersendiri.</p><div class="actions"><button class="btn" data-exam="${c.grade}">Ke halaman kuis →</button><button class="btn secondary" data-home>Pilih materi lain</button></div></div></section></div>`);}
$('homeBrand').onclick=e=>{e.preventDefault();go('home');};$('app').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if('home'in d)go('home');else if('filter'in d){filter=d.filter;home();}else if('lesson'in d)go('lesson',Number(d.lesson));else if('exam'in d)go('exam',Number(d.exam));else if('result'in d)go('result',Number(d.result));else if('cert'in d)go('cert',Number(d.cert));else if('answers'in d)downloadAnswers(Number(d.answers));});
function optionOrder(g,i){const a=[0,1,2,3];let seed=g*391+i*173+57;for(let j=3;j>0;j--){seed=(seed*1664525+1013904223)>>>0;const k=seed%(j+1);[a[j],a[k]]=[a[k],a[j]];}return a;}
function examPage(g){const ex=exams[g];if(!drafts[g])drafts[g]={name:student.name,group:student.group,pg:Array.from({length:20},()=>[]),essay:Array(5).fill('')};const d=drafts[g];page(`<button class="btn secondary" data-home>← Dasbor</button><div class="hero" style="margin-top:20px"><span class="eyebrow">Halaman kuis · Kelas ${g}</span><h1>Uji pemahaman, rayakan proses.</h1><p>20 pilihan ganda kompleks dan 5 esai. Pilih semua opsi yang benar; setiap soal memiliki lebih dari satu jawaban benar.</p></div><form id="examForm" class="panel" style="margin-top:22px"><h2>Identitas peserta didik</h2><div class="identity"><label>Nama lengkap<input required name="studentName" maxlength="100" value="${esc(d.name)}" autocomplete="name"></label><label>Kelas / rombel<input required name="studentGroup" maxlength="40" placeholder="Contoh: ${g} A" value="${esc(d.group)}"></label></div><div class="source"><strong>Petunjuk penilaian</strong><p>PG kompleks: 4 poin jika seluruh pilihan tepat, 0 jika kurang atau ada pilihan salah; maksimum 80. Esai: masing-masing 0–4 poin melalui pemeriksaan guru; maksimum 20. Sertifikat penyelesaian tersedia setelah semua jawaban dikirim, tanpa syarat nilai minimum dan tanpa menunggu penilaian esai.</p><small>Jawaban tersimpan selama sesi halaman ini terbuka. Aplikasi tidak mengirim jawaban ke server sekolah; unduh berkas jawaban untuk diserahkan kepada guru.</small></div><h2>A. Pilihan ganda kompleks</h2>${ex.pg.map((q,i)=>`<fieldset class="question" id="question${i}"><legend>${i+1}. ${q[0]}</legend><small>Pilih semua pernyataan yang benar.</small>${optionOrder(g,i).map((idx,pos)=>`<label class="option"><input type="checkbox" name="pg${i}" value="${idx}" ${d.pg[i].includes(idx)?'checked':''}><span><strong>${String.fromCharCode(65+pos)}.</strong> ${q[1][idx]}</span></label>`).join('')}</fieldset>`).join('')}<h2>B. Esai</h2><p class="muted">Jelaskan dengan bahasamu sendiri dan gunakan contoh yang relevan.</p>${ex.essay.map((q,i)=>`<label class="question" style="display:block" id="essayBox${i}"><strong>${21+i}. ${q[0]}</strong><textarea name="essay${i}" required maxlength="12000" aria-label="Jawaban esai ${i+1}" placeholder="Tulis jawabanmu…">${esc(d.essay[i])}</textarea></label>`).join('')}<p id="examMessage" role="status"></p><div class="actions"><button class="btn" type="submit">Kirim jawaban & lihat hasil →</button><button class="btn secondary" type="button" data-home>Simpan sementara & kembali</button></div></form>`);
const form=$('examForm');function capture(){const f=new FormData(form);d.name=String(f.get('studentName')||'');d.group=String(f.get('studentGroup')||'');d.pg=ex.pg.map((_,i)=>f.getAll('pg'+i).map(Number));d.essay=ex.essay.map((_,i)=>String(f.get('essay'+i)||''));student={name:d.name,group:d.group};}form.oninput=capture;
form.noValidate=true;
function showIssue(message,target){form.querySelectorAll('[data-validation]').forEach(n=>n.remove());const status=$('examMessage');status.textContent=message;status.className='feedback bad';status.setAttribute('role','alert');const note=document.createElement('p');note.dataset.validation='true';note.className='feedback bad';note.textContent=message;target.insertAdjacentElement('beforebegin',note);note.scrollIntoView({behavior:'smooth',block:'center'});const input=target.matches('input,textarea')?target:target.querySelector('input,textarea');if(input){input.setAttribute('aria-invalid','true');input.focus({preventScroll:true});}}
form.onsubmit=e=>{e.preventDefault();capture();form.querySelectorAll('[aria-invalid]').forEach(n=>n.removeAttribute('aria-invalid'));if(!d.name.trim()){showIssue('Isi nama lengkap peserta didik untuk hasil dan sertifikat.',form.elements.studentName);return;}if(!d.group.trim()){showIssue('Isi kelas / rombel peserta didik untuk hasil dan sertifikat.',form.elements.studentGroup);return;}const missing=d.pg.findIndex(a=>a.length===0);if(missing!==-1){showIssue('Soal '+(missing+1)+' belum dijawab. Pilih jawaban terlebih dahulu, lalu kirim kembali.',$('question'+missing));return;}const empty=d.essay.findIndex(a=>!a.trim());if(empty!==-1){showIssue('Esai '+(empty+21)+' belum diisi. Tuliskan jawaban terlebih dahulu, lalu kirim kembali.',$('essayBox'+empty));return;}d.name=d.name.trim();d.group=d.group.trim();let correct=0;ex.pg.forEach((q,i)=>{if(q[2].length===d.pg[i].length&&q[2].every(a=>d.pg[i].includes(a)))correct++;});const id='QH-'+g+'-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase();results[g]={...JSON.parse(JSON.stringify(d)),correct,pgScore:correct*4,essayScores:null,reviewer:'',date:new Date().toISOString(),id};go('result',g);};}
function mountResultCertificate(g){const r=results[g];if(!r)return;const host=document.createElement('section');host.className='no-print';host.innerHTML=`<h2>🏅 E-sertifikat peserta didik</h2><div class="certificate"><div class="seal">۞</div><strong>QURANIHUB</strong><h1>SERTIFIKAT</h1><p>PENYELESAIAN PEMBELAJARAN AL-QUR’AN HADIS</p><p>Diberikan kepada</p><h2>${esc(r.name)}</h2><p>Kelas / rombel: <strong>${esc(r.group)}</strong> · Kuis kelas ${g}</p><p>Telah menyelesaikan 20 pilihan ganda kompleks dan 5 esai.</p><p>${r.essayScores?'Nilai akhir: <strong>'+total(r)+' / 100</strong>':'Poin PG: <strong>'+r.pgScore+' / 80</strong> · Esai menunggu pemeriksaan guru'}</p><p>Guru pembuat website: <strong>Zainul Arifin, S.Pdi</strong></p><small>Nomor: ${esc(r.id)} · ${new Date(r.date).toLocaleDateString('id-ID')}</small><p class="note">${signed()?'Identitas penandatangan tersedia pada versi cetak.':'Draf: lengkapi pengaturan sekolah dan tanda tangan untuk pengesahan.'}</p><button class="btn" data-cert="${g}">Buka sertifikat & simpan PDF →</button></div></section>`;$('app').querySelector('.callout').insertAdjacentElement('afterend',host);}


function total(r){return r.essayScores?r.pgScore+r.essayScores.reduce((s,n)=>s+n,0):null;}
function resultPage(g){const r=results[g];if(!r){go('home');return;}const ex=exams[g];page(`<button class="btn secondary" data-home>← Dasbor</button><section class="panel"><span class="badge">KUIS SELESAI · KELAS ${g}</span><h1>Terima kasih sudah belajar, ${esc(r.name)}!</h1><div class="result-score">${r.pgScore}<small style="font-size:19px"> / 80 poin PG</small></div><p>${r.correct} dari 20 soal PG kompleks tepat seluruhnya.</p><p>${r.essayScores?'<strong>Nilai akhir: '+total(r)+' / 100.</strong> Esai telah diberi skor manual oleh '+esc(r.reviewer)+'.':'<strong>Nilai esai menunggu pemeriksaan guru.</strong> Nilai PG di atas belum merupakan nilai akhir.'}</p><div class="callout"><strong>Setiap proses belajar layak diapresiasi.</strong><p>Sertifikat penyelesaian tersedia untuk semua nilai. Sertifikat ini bukan pernyataan kelulusan atau ketuntasan kompetensi.</p><div class="actions"><button class="btn" data-cert="${g}">🏅 Lihat e-sertifikat</button><button class="btn secondary" data-answers="${g}">↓ Unduh jawaban</button></div></div><details class="review"><summary><strong>Lihat pembahasan 20 soal pilihan ganda</strong></summary>${ex.pg.map((q,i)=>{const ok=q[2].length===r.pg[i].length&&q[2].every(a=>r.pg[i].includes(a));return `<div class="feedback"><strong class="${ok?'good':'bad'}">${i+1}. ${ok?'Tepat · 4 poin':'Belum tepat · 0 poin'}</strong><p>${q[0]}</p><p>Jawabanmu: ${r.pg[i].map(n=>q[1][n]).join('; ')}.</p><p>Kunci: ${q[2].map(n=>q[1][n]).join('; ')}.</p><p>${q[3]}</p></div>`;}).join('')}</details><details class="review"><summary><strong>Jawaban esai & pemeriksaan guru</strong></summary><p class="note">Panel lokal ini tidak memiliki login guru. Skor diisi manual oleh pemeriksa dan dicatat atas nama pemeriksa, bukan diverifikasi otomatis oleh sistem.</p><form id="reviewForm"><label>Nama pemeriksa<input name="reviewer" required maxlength="100" value="${esc(r.reviewer||school.teacher)}"></label>${ex.essay.map((q,i)=>`<div class="question"><strong>${21+i}. ${q[0]}</strong><p style="white-space:pre-wrap">${esc(r.essay[i])}</p><p class="note">Rubrik 0–4: ${q[1]} Skor 0 bila tidak memenuhi aspek. Kredit parsial mengikuti aspek yang benar.</p><label>Skor esai ${i+1} (0–4)<input type="number" name="score${i}" min="0" max="4" step="1" required value="${r.essayScores?r.essayScores[i]:''}"></label></div>`).join('')}<label class="check"><input type="checkbox" required>Saya pemeriksa yang berwenang dan sudah membaca kelima jawaban.</label><button class="btn">Simpan nilai esai</button></form></details></section>`);$('reviewForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const scores=ex.essay.map((_,i)=>Number(f.get('score'+i)));if(scores.some(s=>!Number.isInteger(s)||s<0||s>4))return;const who=String(f.get('reviewer')).trim();if(!who)return;r.essayScores=scores;r.reviewer=who;resultPage(g);};mountResultCertificate(g);}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function downloadAnswers(g){const r=results[g],ex=exams[g];const lines=['QURANIHUB — JAWABAN PESERTA', 'ID: '+r.id,'Nama: '+r.name,'Kelas/rombel: '+r.group,'Kuis: kelas '+g,'Tanggal: '+new Date(r.date).toLocaleString('id-ID'),'PG: '+r.pgScore+'/80','Nilai akhir: '+(r.essayScores?total(r)+'/100':'menunggu pemeriksaan esai'),'Pemeriksa: '+(r.reviewer||'belum ada'),''];ex.pg.forEach((q,i)=>lines.push((i+1)+'. '+q[0],'Jawaban: '+r.pg[i].map(n=>q[1][n]).join('; '),''));ex.essay.forEach((q,i)=>lines.push((i+21)+'. '+q[0],r.essay[i],'Skor esai: '+(r.essayScores?r.essayScores[i]+'/4':'menunggu guru'),''));lines.push('Catatan: catatan lokal tanpa verifikasi server.');saveBlob(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}),'jawaban-kelas-'+g+'-'+r.id+'.txt');}

function signed(){return !!(school.school&&school.teacher&&school.principal&&school.teacherSign&&school.principalSign&&school.consent);}
function certificate(g){const r=results[g];if(!r){go('home');return;}const ready=signed();page(`<div class="no-print"><button class="btn secondary" data-result="${g}">← Kembali ke hasil</button><h2>E-sertifikat penyelesaian</h2><p>${ready?'Gambar tanda tangan berasal dari unggahan pengelola. Ini bukan tanda tangan digital tersertifikasi.':'Sertifikat tetap tersedia. Isi identitas sekolah serta unggah tanda tangan guru dan kepala sekolah melalui tombol Sekolah untuk melengkapinya.'}</p><div class="actions"><button id="printCert" class="btn">Cetak / Simpan PDF</button><button id="saveCert" class="btn secondary">↓ Unduh sertifikat HTML</button></div><p class="note">Untuk PDF: pilih Simpan sebagai PDF, kertas A4 lanskap, matikan header/footer browser, dan aktifkan grafik latar bila diperlukan.</p></div><section class="certificate" id="certificate"><div class="seal">۞</div><strong>QURANIHUB</strong><p class="note">Guru pembuat website: Zainul Arifin, S.Pdi</p><strong style="letter-spacing:2px">${esc(school.school||'IDENTITAS SEKOLAH BELUM DIISI')}</strong><h1>SERTIFIKAT</h1><p style="letter-spacing:3px">PENYELESAIAN PEMBELAJARAN</p><small>Nomor lokal: ${esc(r.id)}</small><p>Diberikan kepada</p><h2>${esc(r.name)}</h2><p>Kelas / rombel: <strong>${esc(r.group)}</strong></p><p>Atas partisipasi dan penyelesaian kuis pembelajaran<br><strong>Al-Qur’an Hadis · Kelas ${g} · Fase ${g===10?'E':'F'}</strong><br>20 pilihan ganda kompleks dan 5 esai</p><p>${r.essayScores?'Nilai akhir: <strong>'+total(r)+' / 100</strong>':'Nilai pilihan ganda: <strong>'+r.pgScore+' / 80</strong> · Esai menunggu pemeriksaan guru'}</p><p>Diselesaikan pada ${new Date(r.date).toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'})}</p><div class="signs"><div>Guru Al-Qur’an Hadis<div class="sign">${school.teacherSign?'<img src="'+school.teacherSign+'" alt="Tanda tangan guru yang diunggah">':'<small>Tanda tangan belum diunggah</small>'}</div><strong>${esc(school.teacher||'Nama guru belum diisi')}</strong></div><div>Kepala Sekolah<div class="sign">${school.principalSign?'<img src="'+school.principalSign+'" alt="Tanda tangan kepala sekolah yang diunggah">':'<small>Tanda tangan belum diunggah</small>'}</div><strong>${esc(school.principal||'Nama kepala sekolah belum diisi')}</strong></div></div><p class="${ready?'note':'draft'}">${ready?'Diterbitkan dari pengaturan lokal sekolah; tidak memiliki verifikasi daring.':'DRAF · Belum disahkan oleh sekolah'}</p><small>Sertifikat penyelesaian, tanpa syarat nilai minimum; bukan bukti kelulusan kompetensi.</small></section>`);applySchoolLogo();$('printCert').onclick=async()=>{applySchoolLogo();await Promise.all(Array.from($('certificate').querySelectorAll('img')).map(img=>img.decode?img.decode().catch(()=>{}):Promise.resolve()));window.print();};$('saveCert').onclick=()=>{applySchoolLogo();const css=document.querySelector('style')?.textContent||(document.getElementById('certificateCssData')?JSON.parse(document.getElementById('certificateCssData').textContent):'')||'body{font-family:serif}.certificate{text-align:center;border:8px double #aa8a4b;padding:30px}.signs{display:flex;justify-content:space-around}.sign img{max-height:80px;max-width:180px}@page{size:A4 landscape;margin:10mm}';const html='<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sertifikat '+esc(r.name)+'</title><style>'+css+'</style></head><body><main>'+$('certificate').outerHTML+'</main></body></html>';saveBlob(new Blob([html],{type:'text/html;charset=utf-8'}),'sertifikat-'+r.id+'.html');};}
$('settingsBtn').onclick=()=>{const f=$('settingsForm');['school','teacher','principal'].forEach(k=>f.elements[k].value=school[k]);f.elements.consent.checked=school.consent;$('teacherFile').value='';$('principalFile').value='';$('settingError').textContent='';$('settings').showModal();};$('closeSettings').onclick=()=>$('settings').close();
async function readSign(input){const file=input.files[0];if(!file)return '';if(!['image/png','image/jpeg'].includes(file.type)||file.size>2*1024*1024)throw Error('Gunakan gambar PNG/JPEG maksimal 2 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Gambar gagal dibaca.'));reader.readAsDataURL(file);});await new Promise((resolve,reject)=>{const image=new Image();image.onload=resolve;image.onerror=()=>reject(Error('Berkas bukan gambar yang valid.'));image.src=data;});return data;}
$('settingsForm').onsubmit=async e=>{e.preventDefault();const f=e.target;const button=f.querySelector('button');button.disabled=true;try{const fields={};for(const k of ['school','teacher','principal']){fields[k]=f.elements[k].value.trim();if(!fields[k])throw Error('Lengkapi nama sekolah, guru, dan kepala sekolah.');}const a=await readSign($('teacherFile')),b=await readSign($('principalFile'));school={...school,...fields,teacherSign:a||school.teacherSign,principalSign:b||school.principalSign,consent:f.elements.consent.checked};$('settings').close();if(route.type==='cert')certificate(route.id);}catch(err){$('settingError').textContent=err.message;}finally{button.disabled=false;}};

function zipFiles(files){const enc=new TextEncoder(),chunks=[],central=[];let offset=0;function crc(bytes){let c=0xffffffff;for(const b of bytes){c^=b;for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xedb88320:0);}return(c^0xffffffff)>>>0;}for(const [name,text]of files){const n=enc.encode(name),d=enc.encode(text),c=crc(d),h=new Uint8Array(30+n.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(12,33,true);v.setUint32(14,c,true);v.setUint32(18,d.length,true);v.setUint32(22,d.length,true);v.setUint16(26,n.length,true);h.set(n,30);chunks.push(h,d);const ch=new Uint8Array(46+n.length),cv=new DataView(ch.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(14,33,true);cv.setUint32(16,c,true);cv.setUint32(20,d.length,true);cv.setUint32(24,d.length,true);cv.setUint16(28,n.length,true);cv.setUint32(42,offset,true);ch.set(n,46);central.push(ch);offset+=h.length+d.length;}const size=central.reduce((n,c)=>n+c.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,files.length,true);ev.setUint16(10,files.length,true);ev.setUint32(12,size,true);ev.setUint32(16,offset,true);return new Blob([...chunks,...central,end],{type:'application/zip'});}
const downloadButton=$('download');if(downloadButton)downloadButton.onclick=()=>{const doc=new DOMParser().parseFromString(originalHTML,'text/html'),style=doc.querySelector('style'),script=doc.querySelector('script');if(!style||!script.textContent.trim())return;const css=style.textContent,js=script.textContent;const link=doc.createElement('link');link.rel='stylesheet';link.href='style.css';style.replaceWith(link);const ext=doc.createElement('script');ext.src='script.js';ext.defer=true;script.replaceWith(ext);doc.getElementById('download').remove();doc.getElementById('schoolLogoData')?.remove();const logoData=doc.createElement('script');logoData.type='application/json';logoData.id='schoolLogoData';logoData.textContent=schoolLogo;doc.head.appendChild(logoData);const certStyle=doc.createElement('script');certStyle.type='application/json';certStyle.id='certificateCssData';certStyle.textContent=JSON.stringify(css);doc.head.appendChild(certStyle);const guide=['QURANIHUB — PETUNJUK','Guru pembuat website: Zainul Arifin, S.Pdi','1. Ekstrak semua berkas ke satu folder.','2. Buka index.html di browser. Tidak memerlukan internet atau pustaka tambahan.','3. Pilih materi dari dasbor. Kuis akhir tersedia per kelas, 25 soal: 20 PG kompleks dan 5 esai.','4. PG dinilai tepat seluruhnya: 4 atau 0 poin. Esai dinilai manual 0–4 per soal melalui panel hasil.','5. Selesaikan semua soal untuk memperoleh sertifikat, berapa pun nilainya.','6. Menu Sekolah: isi identitas dan unggah tanda tangan asli guru/kepala sekolah dengan izin. Tanpa itu sertifikat berstatus draf.','7. Cetak sertifikat menjadi PDF: A4 lanskap, matikan header/footer browser.','8. Unduh jawaban untuk dikirim kepada guru. Semua data dan pengaturan hanya bertahan selama sesi halaman terbuka.','9. Tidak ada akun/login, server, penyimpanan terpusat, verifikasi nomor sertifikat, atau tanda tangan digital tersertifikasi. Nama pemeriksa dan gambar tanda tangan berasal dari input lokal.','10. ZIP tidak menyertakan data pribadi, jawaban peserta, atau gambar tanda tangan dari sesi aktif.','11. Materi dan soal berada di script.js. Gaya berada di style.css. Struktur berada di index.html.','12. Untuk pelaksanaan ujian resmi multi-pengguna, diperlukan server, autentikasi guru, penyimpanan, dan pengesahan sekolah.'].join('\n');saveBlob(zipFiles([['index.html','<!DOCTYPE html>\n'+doc.documentElement.outerHTML],['style.css',css],['script.js',js],['PETUNJUK.txt',guide]]),'QURANIHUB-kelas-10-12.zip');};
function validateContent(){if(chapters.length!==14)throw Error('Jumlah bab tidak sesuai.');for(const g of [10,11,12]){const ex=exams[g];if(ex.pg.length!==20||ex.essay.length!==5)throw Error('Jumlah soal kelas '+g+' tidak sesuai.');for(const q of ex.pg){if(q[1].length!==4||q[2].length<2||q[2].length>3||new Set(q[2]).size!==q[2].length||q[2].some(n=>n<0||n>3))throw Error('Kunci soal tidak sesuai.');}}}
validateContent();go('home');

